// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn check_async_block(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, block: &Block) {
    let own = state.flow.async_group_block;
    state.flow.async_group_block = None;
    let count = block.stmts.len() as i64;
    if count == 0 { return; }
    for (waiter, shared) in diamond_waiters(block, world.words) {
        let waits_for = match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(shared)).node {
            Stmt::Let { value, .. } => id_of(value) as i64,
            _ => continue,
        };
        match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(waiter)).node {
            Stmt::Let { value, .. } => { state.facts.async_abandoned.insert(id_of(value) as i64, waits_for); },
            _ => { },
        }
    }
    let mut group = unsafe { nikaia_std::proven::sub::<i64>(-1, nikaia_std::index::get(&block.stmts, 0).span.start as i64) };
    let mut ends_group = true;
    if own.is_some() { group = nikaia_std::index::or(own, || group); } else if state.flow.async_group.is_some() {
        group = nikaia_std::index::or(state.flow.async_group, || group);
        ends_group = false;
    }
    let mut pending: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut at: i64 = 0;
    for stmt in block.stmts.iter() {
        let mut beside: i64 = 0;
        for wait in pending.iter() {
            let wait = nikaia_std::num::value(wait);
            if wait > at { beside = unsafe { nikaia_std::proven::add::<i64>(beside, 1) }; }
        }
        let last = ends_group && at == count - 1;
        match &stmt.node {
            Stmt::Let { names, value, .. } => {
                match value {
                    Expr::Spawn { child, .. } if { let child = *child; child } => { pending.push(check_child_binding(state, world, block, at, names, value, group)); },
                    Expr::Async(inner, _, _, _) => {
                        let inner = nikaia_std::boxed::open(inner);
                        pending.push(check_async_binding(state, world, block, at, names, value, group, beside, last, &stmt.span));
                        check_async_in(state, inner, group, &stmt.span);
                    },
                    Expr::TryCatch { expr: guarded, .. } => {
                        let guarded = nikaia_std::boxed::open(guarded);
                        match guarded {
                            Expr::Spawn { child, .. } if { let child = *child; child } => { pending.push(check_child_binding(state, world, block, at, names, guarded, group)); },
                            Expr::Async(inner, _, _, _) => {
                                let inner = nikaia_std::boxed::open(inner);
                                pending.push(check_async_binding(state, world, block, at, names, guarded, group, beside, last, &stmt.span));
                                check_async_in(state, inner, group, &stmt.span);
                            },
                            _ => { check_async_in(state, value, group, &stmt.span); },
                        }
                    },
                    Expr::Tuple(parts, _) => {
                        let mut computed: i64 = 0;
                        for part in parts.iter() { if check_async_computes(part) { computed = unsafe { nikaia_std::proven::add::<i64>(computed, 1) }; } }
                        for part in parts.iter() {
                            let task: &Expr = match part {
                                Expr::TryCatch { expr, .. } if { let expr = nikaia_std::boxed::peek(&expr); check_an_async_task(expr) } => { let expr = nikaia_std::boxed::open(expr); expr },
                                _ => part,
                            };
                            match task {
                                Expr::Async(inner, _, _, _) => {
                                    let inner = nikaia_std::boxed::open(inner);
                                    pending.push(check_async_binding(state, world, block, at, names, task, group, unsafe { nikaia_std::proven::sub::<i64>(beside + computed, 1) }, last, &stmt.span));
                                    check_async_in(state, inner, group, &stmt.span);
                                },
                                _ => { check_async_in(state, part, group, &stmt.span); },
                            }
                        }
                    },
                    _ => { check_async_in(state, value, group, &stmt.span); },
                }
            },
            Stmt::Emit(value) => { check_async_in(state, value, group, &stmt.span); },
            Stmt::Expr(value) => {
                match value {
                    Expr::Spawn { child, .. } if { let child = *child; child } => {
                        state.facts.async_waits.insert(id_of(value) as i64, CheckAsyncWait { at: CheckAsyncWaitAt::GroupEnd, group });
                        pending.push(count);
                    },
                    Expr::TryCatch { expr: guarded, .. } if { let guarded = nikaia_std::boxed::peek(&guarded); check_a_child_task(guarded) } => {
                        let guarded = nikaia_std::boxed::open(guarded);
                        state.facts.async_waits.insert(id_of(guarded) as i64, CheckAsyncWait { at: CheckAsyncWaitAt::GroupEnd, group });
                        pending.push(count);
                    },
                    Expr::TryCatch { expr: guarded, .. } if { let guarded = nikaia_std::boxed::peek(&guarded); check_an_async_task(guarded) } => {
                        let guarded = nikaia_std::boxed::open(guarded);
                        state.facts.async_waits.insert(id_of(guarded) as i64, CheckAsyncWait { at: CheckAsyncWaitAt::GroupEnd, group });
                        if last && beside == 0 { state.a_task_with_nothing_beside_it(&stmt.span, "it is the last statement of its group, which waits for it at once"); }
                        pending.push(count);
                        match guarded {
                            Expr::Async(inner, _, _, _) => { let inner = nikaia_std::boxed::open(inner); check_async_in(state, inner, group, &stmt.span); },
                            _ => { },
                        }
                    },
                    Expr::Async(inner, _, _, _) => {
                        let inner = nikaia_std::boxed::open(inner);
                        state.facts.async_waits.insert(id_of(value) as i64, CheckAsyncWait { at: CheckAsyncWaitAt::GroupEnd, group });
                        if last && beside == 0 { state.a_task_with_nothing_beside_it(&stmt.span, "it is the last statement of its group, which waits for it at once"); }
                        pending.push(count);
                        check_async_in(state, inner, group, &stmt.span);
                    },
                    _ => { check_async_in(state, value, group, &stmt.span); },
                }
            },
            Stmt::Comptime { value, .. } => { check_async_in(state, value, group, &stmt.span); },
            Stmt::Assign { target, value, .. } => {
                check_async_in(state, target, group, &stmt.span);
                check_async_in(state, value, group, &stmt.span);
            },
            Stmt::For { iter, .. } => { check_async_in(state, iter, group, &stmt.span); },
            Stmt::While { cond, .. } => { check_async_in(state, cond, group, &stmt.span); },
            Stmt::Return(value) => { if value.is_some() { check_async_in(state, match value { Some(__nikaia_value) => __nikaia_value, None => return }, group, &stmt.span); } },
            Stmt::Break => { },
            Stmt::Continue => { },
        }
        at = unsafe { nikaia_std::proven::add::<i64>(at, 1) };
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
#[allow(clippy::too_many_arguments)]
pub(crate) fn check_async_binding(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, block: &Block, at: i64, names: &[winnow_grammar::Symbol], task: &Expr, group: i64, others: i64, last: bool, span: &Span) -> i64 {
    let count = block.stmts.len() as i64;
    let mut wanted: collections::BTreeSet<String> = collections::BTreeSet::new();
    for name in names.iter() {
        let name = *name;
        wanted.insert(nikaia_std::block::Text::from(world.words.resolve(name).to_string()));
    }
    let mut named = count;
    let mut readers = 0;
    let mut index: i64 = 0;
    for stmt in block.stmts.iter() {
        if index > at && named == count {
            let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
            names_in_statement(&stmt.node, world.words, &mut seen);
            for name in wanted.iter() {
                if seen.contains(name) {
                    if starts_a_task(&stmt.node) {
                        readers += 1;
                        break;
                    }
                    named = index;
                }
            }
        }
        index = unsafe { nikaia_std::proven::add::<i64>(index, 1) };
    }
    if readers > 1 || readers > 0 && named < count { state.facts.async_shared.insert(id_of(task) as i64); } else if readers == 1 { state.facts.async_lone.insert(id_of(task) as i64); }
    if named == count {
        state.facts.async_waits.insert(id_of(task) as i64, CheckAsyncWait { at: CheckAsyncWaitAt::GroupEnd, group });
        if last && others == 0 { state.a_task_with_nothing_beside_it(span, "nothing names its binding, and it is the last statement of its group, which waits for it at once"); }
        return count;
    }
    state.facts.async_waits.insert(id_of(task) as i64, CheckAsyncWait { at: CheckAsyncWaitAt::BeforeStatement(nikaia_std::index::get(&block.stmts, nikaia_std::index::at(named)).span.start as i64), group });
    if named == unsafe { nikaia_std::proven::add::<i64>(at, 1) } && others == 0 { state.a_task_with_nothing_beside_it(span, "its binding is named in the very next statement, which waits for it"); }
    named
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn check_child_binding(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, block: &Block, at: i64, names: &[winnow_grammar::Symbol], task: &Expr, group: i64) -> i64 {
    let count = block.stmts.len() as i64;
    let mut wanted: collections::BTreeSet<String> = collections::BTreeSet::new();
    for name in names.iter() {
        let name = *name;
        wanted.insert(nikaia_std::block::Text::from(world.words.resolve(name).to_string()));
    }
    let mut named = false;
    let mut index: i64 = 0;
    for stmt in block.stmts.iter() {
        if index > at && !named {
            let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
            names_in_statement(&stmt.node, world.words, &mut seen);
            for name in wanted.iter() { if seen.contains(name) { named = true; } }
        }
        index = unsafe { nikaia_std::proven::add::<i64>(index, 1) };
    }
    let mut wait = CheckAsyncWaitAt::GroupEnd;
    if named { wait = CheckAsyncWaitAt::Handle; }
    state.facts.async_waits.insert(id_of(task) as i64, CheckAsyncWait { at: wait, group });
    count
}

