// this was written - see `contracts::sync`.
pub(crate) fn check_async_in(state: &mut CheckState, expr: &Expr, group: i64, span: &Span) {
    match expr {
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            let mut parts: Vec<&Expr> = vec![func];
            parts.reserve(args.iter().size_hint().0); for arg in args.iter() { parts.push(arg); }
            check_async_operands(state, &parts, id_of(expr) as i64, group, span);
        },
        Expr::MethodCall { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            let mut parts: Vec<&Expr> = vec![receiver];
            parts.reserve(args.iter().size_hint().0); for arg in args.iter() { parts.push(arg); }
            check_async_operands(state, &parts, id_of(expr) as i64, group, span);
        },
        Expr::SafeMethod { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            let mut parts: Vec<&Expr> = vec![receiver];
            parts.reserve(args.iter().size_hint().0); for arg in args.iter() { parts.push(arg); }
            check_async_operands(state, &parts, id_of(expr) as i64, group, span);
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let parts: Vec<&Expr> = vec![lhs, rhs];
            check_async_operands(state, &parts, id_of(expr) as i64, group, span);
        },
        Expr::Tuple(items, _) => {
            let mut parts: Vec<&Expr> = vec![];
            parts.reserve(items.iter().size_hint().0); for item in items.iter() { parts.push(item); }
            check_async_operands(state, &parts, id_of(expr) as i64, group, span);
        },
        Expr::Spawn { child, .. } if { let child = *child; child } => { state.facts.async_waits.insert(id_of(expr) as i64, CheckAsyncWait { at: CheckAsyncWaitAt::Handle, group }); },
        Expr::Async(inner, _, _, _) => {
            let inner = nikaia_std::boxed::open(inner);
            state.facts.async_waits.insert(id_of(expr) as i64, CheckAsyncWait { at: CheckAsyncWaitAt::Before(id_of(expr) as i64), group });
            state.a_task_with_nothing_beside_it(span, "where it stands, its value is needed at once");
            check_async_in(state, inner, group, span);
        },
        _ => { for child in child_exprs_of(expr) { check_async_in(state, child, group, span); } },
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn check_async_operands(state: &mut CheckState, parts: &[&Expr], at: i64, group: i64, span: &Span) {
    let mut computed = 0;
    for part in parts.iter() {
        let part = *part;
        if check_async_computes(part) { computed += 1; }
    }
    for part in parts.iter() {
        let part = *part;
        let task: &Expr = match part {
            Expr::TryCatch { expr, .. } if { let expr = nikaia_std::boxed::peek(&expr); check_an_async_task(expr) } => { let expr = nikaia_std::boxed::open(expr); expr },
            _ => part,
        };
        match task {
            Expr::Async(inner, _, _, _) => {
                let inner = nikaia_std::boxed::open(inner);
                state.facts.async_waits.insert(id_of(task) as i64, CheckAsyncWait { at: CheckAsyncWaitAt::Before(at), group });
                if computed < 2 { state.a_task_with_nothing_beside_it(span, "nothing beside it in the same call or operation is computed while it runs"); }
                check_async_in(state, inner, group, span);
            },
            _ => { check_async_in(state, part, group, span); },
        }
    }
}

